      if (settled) return;
      if (typeof fetch !== 'function') { finish(false); return; }
      fetch(CLIENTS5_URL + encodeURIComponent(text), { mode: 'cors', credentials: 'omit' })
        .then((r) => (r.ok ? r.text() : Promise.reject(new Error('http ' + r.status))))
