      const a = new Audio(url);
      this._audioEl = a;
      this._markSource('google');
      a.volume = this.audio.muted ? 0 : 1;
      a.onended = () => finish(true);
      a.onerror = () => tryJson();
      const p = a.play();
      if (p && typeof p.catch === 'function') p.catch(() => tryJson());
