     src.buffer = buf;
     const f = ctx.createBiquadFilter();
     f.type = 'bandpass';
     f.frequency.value = freq;
     const g = ctx.createGain();
     g.gain.value = gainV;
     src.connect(f).connect(g).connect(this.audio.master || ctx.destination);
