import { moveBox } from '/home/runner/hub-work/nuar-det/code/src/world/Collision.js';

let pass = 0, fail = 0;
const check = (name, cond) => {
  if (cond) { pass++; console.log('ok  ', name); }
  else { fail++; console.log('FAIL', name); }
};

// персонаж: halfH 0.9 => центр y = pos.y + 0.9
const H = 0.9, W = 0.35, D = 0.35;
const box = (x, y, z, grounded = true) => ({ x, y, z, halfW: W, halfH: H, halfD: D, grounded });
// уступ высотой 0.1, игрок стоит на полу y=0 (центр 0.9), верх уступа = 0.1
const ledge = { minX: 1, maxX: 5, minY: -5, maxY: 0.1, minZ: -1, maxZ: 1 };
const floor = { minX: -50, maxX: 50, minY: -5, maxY: 0, minZ: -50, maxZ: 50 };
const dt = 1 / 60;

// 1. авто-шаг: идём в уступ, должны перешагнуть и встать на него
{
  const r = moveBox(box(0, H, 0), { x: 3 * dt, y: -24 * dt * dt, z: 0 }, [floor, ledge], [], 0.12);
  check('autostep: перешагнул уступ', r.pos.x > 1.2);
  check('autostep: встал наверх (y=0.1)', Math.abs(r.pos.y - 0.1) < 1e-6);
  check('autostep: grounded', r.grounded === true);
}

// 2. высокий уступ (0.5) — шагать нельзя
{
  const tall = { minX: 1, maxX: 5, minY: -5, maxY: 0.5, minZ: -1, maxZ: 1 };
  const r = moveBox(box(0, H, 0), { x: 3 * dt, y: -24 * dt * dt, z: 0 }, [floor, tall], [], 0.12);
  check('высокий уступ: не прошли', r.pos.x <= 1 - W + 1e-6);
  check('высокий уступ: остались на полу', Math.abs(r.pos.y - 0) < 1e-6);
}

// 3. в воздухе шага не будет
{
  const r = moveBox(box(0, H, 0, false), { x: 3 * dt, y: -2 * dt, z: 0 }, [floor, ledge], [], 0.12);
  check('в воздухе: не перешагнули', r.pos.x <= 1 - W + 1e-6);
}

// 4. шаг в стену не поднимает в воздух, а на земле упирается корректно
{
  const wall = { minX: 1, maxX: 5, minY: 0, maxY: 3, minZ: -1, maxZ: 1 };
  const r = moveBox(box(0, H, 0), { x: 3 * dt, y: -24 * dt * dt, z: 0 }, [floor, wall], [], 0.12);
  check('стена: остановились', Math.abs(r.pos.x - (1 - W)) < 1e-6);
  check('стена: hitWall.x = 1', r.hitWall.x === 1);
  check('стена: остались на полу', Math.abs(r.pos.y - 0) < 1e-6);
  check('стена: bump', r.bump === true);
}

// 5. низкий потолок блокирует шаг
{
  const ceil = { minX: -1, maxX: 5, minY: 1.0, maxY: 3, minZ: -1, maxZ: 1 };
  const r = moveBox(box(0, H, 0), { x: 3 * dt, y: -24 * dt * dt, z: 0 }, [floor, ledge, ceil], [], 0.12);
  check('потолок: шаг заблокирован', r.pos.x <= 1 - W + 1e-6);
}

// 6. обычное падение на пол
{
  const r = moveBox(box(0, 1.0, 0), { x: 0, y: -2 * dt, z: 0 }, [floor], [], 0.12);
  check('падение: приземлились', Math.abs(r.pos.y - 0) < 1e-6 && r.grounded);
}

// 7. диагональ в открытом поле
{
  const r = moveBox(box(0, H, 0), { x: 0.05, y: -24 * dt * dt, z: 0.05 }, [floor], [], 0.12);
  check('открытое поле: движение не блокируется', r.pos.x > 0.04 && r.pos.z > 0.04);
}

// 8. односторонняя платформа: падение сверху ловит, снизу проходит
{
  const plat = { minX: -1, maxX: 1, minY: 0, maxY: 0.1, minZ: -1, maxZ: 1 };
  const above = moveBox(box(0, 1.2, 0), { x: 0, y: -2 * dt, z: 0 }, [], [plat], 0.12);
  check('платформа сверху: сели', Math.abs(above.pos.y - 0.1) < 1e-6 && above.grounded);
  const below = moveBox(box(0, -0.5, 0), { x: 0, y: 2 * dt, z: 0 }, [], [plat], 0.12);
  check('платформа снизу: прошли', below.pos.y < -0.5);
}

// 9. потолок над головой
{
  const ceil = { minX: -1, maxX: 1, minY: 1.5, maxY: 3, minZ: -1, maxZ: 1 };
  const r = moveBox(box(0, 0.7, 0), { x: 0, y: 2 * dt, z: 0 }, [floor, ceil], [], 0.12);
  check('потолок: остановились', r.pos.y < 1.5 - H + 1e-6 && r.hitCeiling);
}

// 10. шаг по Z-оси
{
  const ledgeZ = { minX: -1, maxX: 1, minY: -5, maxY: 0.1, minZ: 1, maxZ: 5 };
  const r = moveBox(box(0, H, 0), { x: 0, y: -24 * dt * dt, z: 3 * dt }, [floor, ledgeZ], [], 0.12);
  check('autostep по Z', r.pos.z > 1.2 && Math.abs(r.pos.y - 0.1) < 1e-6);
}

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);

