import { moveBox } from '/home/runner/hub-work/nuar-det/code/src/world/Collision.js';

let pass = 0, fail = 0;
const check = (name, cond) => {
  if (cond) { pass++; console.log('ok  ', name); }
  else { fail++; console.log('FAIL', name); }
};

// box.y — ЦЕНТР тела (так его строит Player: pos.y + halfH),
// moveBox возвращает тоже центр, а Player потом вычитает halfH.
const H = 0.9, W = 0.35, D = 0.35;
const mk = (x, y, z, grounded) => ({ x, y, z, halfW: W, halfH: H, halfD: D, grounded });
const V = -24; // гравитация

// прогон N кадров: держим горизонтальную скорость, гравитация каждый кадр
function walk(solids, oneWays, { frames = 240, vx = 0, vz = 0, start, stepHeight = 0.12 }) {
  let b = start;
  let grounded = true;
  let ty = 0;
  for (let i = 0; i < frames; i++) {
    const dt = 1 / 60;
    ty = Math.max(-32, ty + V * dt);
    const r = moveBox(b, { x: vx * dt, y: ty * dt, z: vz * dt }, solids, oneWays, stepHeight);
    b = mk(r.pos.x, r.pos.y, r.pos.z, r.grounded);
    grounded = r.grounded;
    if (grounded) ty = 0;
  }
  return { pos: b, grounded, feet: b.y - H };
}

const floor = { minX: -50, maxX: 50, minY: -5, maxY: 0, minZ: -50, maxZ: 50 };
const start = mk(0, H, 0, true);

// 1. авто-шаг на низкий уступ 0.1
{
  const ledge = { minX: 1, maxX: 5, minY: -5, maxY: 0.1, minZ: -1, maxZ: 1 };
  const r = walk([floor, ledge], [], { vx: 6.4, start, frames: 200 });
  check('авто-шаг: перешагнул уступ', r.pos.x > 1.2);
  check('авто-шаг: стоит на уступе (y=0.1)', Math.abs(r.feet - 0.1) < 1e-3);
  check('авто-шаг: grounded', r.grounded === true);
}

// 2. высокий уступ 0.5 — не перешагиваем
{
  const tall = { minX: 1, maxX: 5, minY: -5, maxY: 0.5, minZ: -1, maxZ: 1 };
  const r = walk([floor, tall], [], { vx: 6.4, start, frames: 200 });
  check('высокий уступ: не прошли', r.pos.x <= 1 - W + 1e-3);
  check('высокий уступ: остались на полу', Math.abs(r.feet - 0) < 1e-3);
}

// 3. в воздухе шага нет
{
  const ledge = { minX: 1, maxX: 5, minY: -5, maxY: 0.1, minZ: -1, maxZ: 1 };
  const b = mk(0, H + 0.5, 0, false);
  const r = moveBox(b, { x: 0.2, y: -0.1, z: 0 }, [floor, ledge], [], 0.12);
  check('в воздухе: не перешагнули', r.pos.x <= 0.2 + 1e-6 && r.pos.y > H);
}

// 4. стена не пропускает
{
  const wall = { minX: 1, maxX: 5, minY: 0, maxY: 3, minZ: -1, maxZ: 1 };
  const r = walk([floor, wall], [], { vx: 6.4, start, frames: 200 });
  check('стена: остановились у стены', Math.abs(r.pos.x - (1 - W)) < 1e-3);
  check('стена: остались на полу', Math.abs(r.feet - 0) < 1e-3);
}

// 4b. одиночный кадр у стены: hitWall и bump
{
  const wall = { minX: 1, maxX: 5, minY: 0, maxY: 3, minZ: -1, maxZ: 1 };
  const r = moveBox(mk(0.5, H, 0, true), { x: 0.6, y: -0.01, z: 0 }, [floor, wall], [], 0.12);
  check('стена: hitWall.x = 1', r.hitWall.x === 1);
  check('стена: bump = true', r.bump === true);
}

// 5. низкий потолок блокирует шаг
{
  const ledge = { minX: 1, maxX: 5, minY: -5, maxY: 0.1, minZ: -1, maxZ: 1 };
  const ceil = { minX: -1, maxX: 5, minY: 1.0, maxY: 3, minZ: -1, maxZ: 1 };
  const r = walk([floor, ledge, ceil], [], { vx: 6.4, start, frames: 200 });
  check('потолок: шаг заблокирован', r.pos.x <= 1 - W + 1e-3);
}

// 6. падение на пол
{
