  const r = walk([floor, ledge, ceil], [], { vx: 6.4, start, frames: 200 });
  check('щель: остались на полу', Math.abs(r.feet - 0) < 1e-3);
}

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);

