import { moveBox } from '/home/runner/hub-work/nuar-det/code/src/world/Collision.js';

const H = 0.9, W = 0.35, D = 0.35;
const mk = (x, y, z, grounded) => ({ x, y, z, halfW: W, halfH: H, halfD: D, grounded });

// Падаем сверху на одностороннюю платформу (верх = 0.1).
// Шаг dt: пусть игрок опускается с 0.05 над верхом до 0.05 под ним за кадр.
const plat = { minX: -1, maxX: 1, minY: 0, maxY: 0.1, minZ: -1, maxZ: 1 };

let y = 0.1 + 0.05 + H; // низ тела на 0.05 выше верха платформы
const dy = -0.1;         // за кадр опускается на 0.1 -> пересечёт верх
const r = moveBox(mk(0, y, 0, false), { x: 0, y: dy, z: 0 }, [], [plat], 0.12);

console.log('старт: низ тела =', (y - H).toFixed(4), 'верх платформы =', plat.maxY);
console.log('после: pos.y =', r.pos.y.toFixed(4), 'низ тела =', (r.pos.y - H).toFixed(4), 'grounded =', r.grounded);
console.log(r.grounded ? 'OK: сел на платформу' : 'BUG: провалился сквозь платформу');

