// падению, из-за чего платформа пропускала персонажа насквозь.
if (delta.y < 0) {
  const prevBottom = box.y - halfH;
  for (const p of oneWayPlatforms) {
    if (x + halfW > p.minX && x - halfW < p.maxX &&
        z + halfD > p.minZ && z - halfD < p.maxZ) {
      const newBottom = y - halfH;
      if (prevBottom >= p.maxY - EPS && newBottom <= p.maxY + EPS) {
        y = p.maxY + halfH;
        grounded = true;
        break;
      }
    }
  }
}

