const which=process.argv[2]||'new';
const { moveBox } = await import(which==='orig'?'/tmp/opencode/Collision.orig.js':'/home/runner/hub-work/nuar-det/code/src/world/Collision.js');
const H=0.9,W=0.35,D=0.35;
const mk=(x,y,z,g)=>({x,y,z,halfW:W,halfH:H,halfD:D,grounded:g});
const bx={minX:x=>0}; // placeholder
const boxOf=(x,y,z)=>({minX:x-W,maxX:x+W,minY:y-H,maxY:y+H,minZ:z-D,maxZ:z+D});
// глубина пересечения по каждой оси
const depth=(a,b)=>Math.min(a.maxX-b.minX,b.maxX-a.minX, a.maxY-b.minY,b.maxY-a.minY, a.maxZ-b.minZ,b.maxZ-a.minZ);
let seed=999;
const rnd=()=>{seed=(seed*1103515245+12345)&0x7fffffff;return seed/0x7fffffff;};
const range=(a,b)=>a+(b-a)*rnd();
const floor={minX:-60,maxX:60,minY:-5,maxY:0,minZ:-60,maxZ:60};
const solids=[floor], oneWays=[];
for(let i=0;i<40;i++){
  const w=range(0.8,2.5), d=range(0.8,2.5), h=range(0.04,0.12);
  solids.push({minX:range(-14,14),minY:0,minZ:range(-14,14),maxX:0,maxY:h,maxZ:0});
  const s=solids[solids.length-1]; s.maxX=s.minX+w; s.maxZ=s.minZ+d;
}
const TOL=0.01;
let deep=0, worst=0, frames=0;
for(let run=0;run<305;run++){
  let b=mk(range(-10,10),H,range(-10,10),true), ty=0;
  for(let f=0;f<400;f++){
    const dt=1/60, ang=f*0.05;
    ty=Math.max(-32,ty-24*dt);
    const r=moveBox(b,{x:Math.sin(ang)*5*dt,y:ty*dt,z:Math.cos(ang)*5*dt},solids,oneWays,0.12);
    const bb=boxOf(r.pos.x,r.pos.y,r.pos.z);
    for(const s of solids){
      const d=depth(bb,s);
      if(d>0){ if(d>worst)worst=d; if(d>TOL){deep++;} break; }
    }
    b=mk(r.pos.x,r.pos.y,r.pos.z,r.grounded);
    if(r.grounded)ty=0;
    frames++;
  }
}
console.log(`[${which}] кадров=${frames} глубоких(>${TOL})=${deep} макс.глубина=${worst.toFixed(6)}`);
EOF
