import { moveBox } from '/home/runner/hub-work/nuar-det/code/src/world/Collision.js';
const H=0.9,W=0.35,D=0.35;
const mk=(x,y,z,g)=>({x,y,z,halfW:W,halfH:H,halfD:D,grounded:g});
let pass=0,fail=0;
const check=(n,c)=>{c?(pass++,console.log('ok  ',n)):(fail++,console.log('FAIL',n));};

const floor={minX:-50,maxX:50,minY:-5,maxY:0,minZ:-50,maxZ:50};
const plat={minX:-2,maxX:2,minY:0,maxY:0.2,minZ:-2,maxZ:2};
const JUMP_VEL=9.5, G=-24, dt=1/60;

// стоим на полу под платформой
let b=mk(0,H,0,true), ty=0;
for(let f=0;f<40;f++){ // осесть
  ty=Math.max(-32,ty+G*dt);
  const r=moveBox(b,{x:0,y:ty*dt,z:0},[floor],[plat],0.12);
  b=mk(r.pos.x,r.pos.y,r.pos.z,r.grounded); if(r.grounded)ty=0;
}
check('под платформой стоим на полу', Math.abs(b.y-H)<1e-6);

// прыжок вверх сквозь платформу
ty=JUMP_VEL; let passedThrough=false, landedTop=false, maxFeet=b.y-H;
for(let f=0;f<200;f++){
  const r=moveBox(b,{x:0,y:ty*dt,z:0},[floor],[plat],0.12);
  b=mk(r.pos.x,r.pos.y,r.pos.z,r.grounded);
  const feet=b.y-H;
  if(feet>0.2) passedThrough=true;              // ноги выше верха платформы
  if(passedThrough && r.grounded && feet>0.15) { landedTop=true; break; }
  if(r.grounded) ty=0; else ty=Math.max(-32,ty+G*dt);
}
check('прыжок проходит сквозь платформу', passedThrough);
check('приземлился на верх платформы (0.2)', landedTop && Math.abs((b.y-H)-0.2)<1e-3);

// спуститься вниз с платформы
ty=-1; let fell=false;
for(let f=0;f<200;f++){
  const r=moveBox(b,{x:0,y:ty*dt,z:0},[floor],[plat],0.12);
  b=mk(r.pos.x,r.pos.y,r.pos.z,r.grounded);
  if(Math.abs(b.y-H)<1e-3 && r.grounded){fell=true;break;}
  if(r.grounded)ty=0; else ty=Math.max(-32,ty+G*dt);
}
check('сошёл с платформы вниз на пол', fell);
console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail?1:0);
EOF
