// Стандартный свип: сдвинуть бокс на delta и развести его со списком твёрдых
// боксов. Возвращает { pos, grounded, hitWall, hitCeiling, bump }.
export function moveBox(box, delta, solids, oneWayPlatforms, stepHeight = 0.12) {
  let x = box.x, y = box.y, z = box.z;
  const halfW = box.halfW, halfH = box.halfH, halfD = box.halfD;

  let grounded = false;
  let hitWall = { x: 0, z: 0 };
  let hitCeiling = false;

  const dx = delta.x;
  const dz = delta.z;

  // Один горизонтальный проход на заданной высоте atY. Условия «мы уже были
  // снаружи» проверяются по текущему значению координаты, как в исходном коде,
  // иначе углы и ящики вели бы себя иначе.
  const sweepHorizontal = (fromX, fromZ, atY) => {
    let ox = fromX;
    let oz = fromZ;
    let hx = 0;
    let hz = 0;
    let blockedX = false;
    let blockedZ = false;

    if (dx !== 0) {
      for (const s of solids) {
        if (atY + halfH > s.minY && atY - halfH < s.maxY &&
            fromZ + halfD > s.minZ && fromZ - halfD < s.maxZ) {
          if (dx > 0 && fromX + dx + halfW > s.minX && ox + halfW <= s.minX + EPS) {
            ox = s.minX - halfW; blockedX = true; hx += 1;
          } else if (dx < 0 && fromX + dx - halfW < s.maxX && ox - halfW >= s.maxX - EPS) {
            ox = s.maxX + halfW; blockedX = true; hx -= 1;
          }
        }
      }
      if (!blockedX) ox = fromX + dx;
    }

    if (dz !== 0) {
      for (const s of solids) {
        if (atY + halfH > s.minY && atY - halfH < s.maxY &&
            ox + halfW > s.minX && ox - halfW < s.maxX) {
          if (dz > 0 && fromZ + dz + halfD > s.minZ && oz + halfD <= s.minZ + EPS) {
            oz = s.minZ - halfD; blockedZ = true; hz += 1;
          } else if (dz < 0 && fromZ + dz - halfD < s.maxZ && oz - halfD >= s.maxZ - EPS) {
            oz = s.maxZ + halfD; blockedZ = true; hz -= 1;
          }
        }
      }
      if (!blockedZ) oz = fromZ + dz;
    }

    return { x: ox, z: oz, hx, hz, blocked: blockedX || blockedZ };
  };

  const freeAt = (px, py, pz) => !solids.some((s) => aabbOverlap({
    minX: px - halfW, maxX: px + halfW,
    minY: py - halfH, maxY: py + halfH,
    minZ: pz - halfD, maxZ: pz + halfD,
  }, s));

  let sweep = sweepHorizontal(x, z, y);
  x = sweep.x;
  z = sweep.z;
  hitWall.x += sweep.hx;
  hitWall.z += sweep.hz;

  // Авто-шаг на низкий уступ. Раньше он жил в ветке `!delta.y`, но игрок всегда
  // падает с гравитацией, то есть delta.y ненулевой в каждом кадре, — шаг не
  // срабатывал никогда. Теперь пробуем тот же сдвиг на stepHeight выше и
  // принимаем его, только если он ушёл дальше и под головой свободно.
  let stepped = false;
  if (sweep.blocked && stepHeight > 0 && box.grounded) {
    const up = y + stepHeight;
    // Повторяем свип от ИСХОДНОЙ позиции, а не от уже сдвинутой: иначе delta
    // применился бы дважды и бокс проникал внутрь соседнего уступа.
    const step = sweepHorizontal(box.x, box.z, up);
    const before = Math.abs(sweep.x - box.x) + Math.abs(sweep.z - box.z);
    const gained = Math.abs(step.x - box.x) + Math.abs(step.z - box.z);
    if (gained > before + EPS && !step.blocked && freeAt(step.x, up, step.z)) {
      y = up;
      x = step.x;
      z = step.z;
      hitWall.x = step.hx;
      hitWall.z = step.hz;
      // оседаем на уступ в том же кадре, иначе персонаж несколько кадров
      // висит над ним, пока гравитация не дотянет
      let top = -Infinity;
      for (const s of solids) {
        if (s.maxY <= y - halfH + EPS && s.maxY > top &&
            x + halfW > s.minX && x - halfW < s.maxX &&
            z + halfD > s.minZ && z - halfD < s.maxZ) top = s.maxY;
      }
      if (top > -Infinity) { y = top + halfH; grounded = true; stepped = true; }
    }
  }

